    36	    async fn get_sitting_members(&self) -> Result<Vec<ParliamentMember>, ParliamentApiError> {
    37	        let batch = self.batch_size;
    38	        let mut offset = 0;
    39	        let mut members = Vec::new();
    40	        loop {
    41	            let url = format!(
    42	                "{BASE_URL}/api/Members/Search?House=1&IsCurrentMember=true&skip={offset}&take={batch}"
    43	            );
    44	            let result = self
    45	                .client
    46	                .get(url)
    47	                .send()
    48	                .await
    49	                .map_err(|e| ApiError::ResponseError(e.to_string()))?;
    50	
    51	            let bytes = result
    52	                .bytes()
    53	                .await
    54	                .map_err(|e| ApiError::ResponseError(e.to_string()))?;
    55	
    56	            let response: ParliamentResponse = serde_json::from_slice(&bytes)
    57	                .map_err(|e| ApiError::ResponseError(e.to_string()))?;
    58	
    59	            println!("retrieved {batch} records from offset {offset}");
    60	            offset += response.items.len();
    61	            members.extend(response.items);
    62	
    63	            if members.len() == response.total_results {
    64	                println!("received all members");
    65	                break;
    66	            }
    67	        }
    68	
    69	        Ok(members
    70	            .into_iter()
    71	            .map(|m| {
    72	                ParliamentMember::new(
    73	                    m.value.name,
    74	                    m.value.id,
    75	                    m.value.party.name,
    76	                    m.value.membership.membership_from,
    77	                )
    78	            })
    79	            .collect())
    80	    }
