//! A collection of outbound adapters for the `exposed` project

mod entity_search_pipeline;
mod file_system;
mod funder;
mod parliament_api;
mod parliament_member;
mod postgres;

pub use postgres::ExposedDatabase;
//! Collection of repositories for the `exposed` project

/// Access data about funders
pub mod funder_repository;

/// Access data about MPs
pub mod parliament_member_repository;

/// Pubilc API for UK Parliament  
pub mod parliament_api;

/// Store for cleaning parliament API data;
pub mod entity_ingestion_pipline;
use std::sync::Arc;

use crate::{
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{config::ServerConfig, routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Starts an `exposed` HTTP server
///
/// # Errors
/// - When the TCP listener cannot attach
pub async fn serve_exposed(config: &ServerConfig) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    let port = config.port;
    let listener = tokio::net::TcpListener::bind(format!("0.0.0.0:{port}")).await?;

    axum::serve(listener, router).await?;

    Ok(())
}
