L226:     trait Trait{}
L227:     trait GenericTrait<T> {}
L228:     trait HasAssocType { type Ty; }
L229:     struct Struct;
L230:     struct GenericStruct<T>(T);
L231:     struct ConstGenericStruct<const N: usize>([(); N]);
L232:     // T constrains by being an argument to GenericTrait.
L233:     impl<T> GenericTrait<T> for i32 { /* ... */ }
L234: 
L235:     // T constrains by being an argument to GenericStruct
L236:     impl<T> Trait for GenericStruct<T> { /* ... */ }
L237:     // Likewise, N constrains by being an argument to ConstGenericStruct
L238:     impl<const N: usize> Trait for ConstGenericStruct<N> { /* ... */ }
L239: 
L240:     // T constrains by being in an associated type in a bound for type `U` which is
L241:     // itself a generic parameter constraining the trait.
L242:     impl<T, U> GenericTrait<U> for u32 where U: HasAssocType<Ty = T> { /* ... */ }
L243: 
L244:     // Like previous, except the type is `(U, isize)`. `U` appears inside the type
L245:     // that includes `T`, and is not the type itself.
L246:     impl<T, U> GenericStruct<U> where (U, isize): HasAssocType<Ty = T> { /* ... */ }
L247:     }`
L248: Examples of non-constraining situations:
