L264:     }
L265: 
L266:     // T is used as an associated type in the bounds for U, but U does not constrain.
L267:     impl<T, U> Struct where U: HasAssocType<Ty = T> { /* ... */ }
L268: 
L269:     // T is used in the bounds, but not as an associated type, so it does not constrain.
L270:     impl<T, U> GenericTrait<U> for u32 where U: GenericTrait<T> {}
